#endif


BENCHMARK_TEMPLATE(BM_RandSampleIteratorExplicit, std::mt19937_64)->Apply(AddRandomAccessSamplingCases)->ArgNames({"range_size", "request"});
BENCHMARK_TEMPLATE(BM_RandSampleContainerExplicit, std::mt19937_64)->Apply(AddContainerSamplingCases)->ArgNames({"range_size", "request"});
BENCHMARK_TEMPLATE(BM_RandSampleReservoirExplicit, std::mt19937_64)->Apply(AddReservoirSamplingCases)->ArgNames({"range_size", "request"});
static void BM_ShuffleDefault(benchmark::State& state) {
    auto values = MakeSamplingVector(static_cast<std::size_t>(state.range(0)));
    PrepareDefaultSamplingEngine();
    for (auto iteration : state) {
        RandX::RandShuffle(values);
        auto data = values.data(); benchmark::DoNotOptimize(data); benchmark::ClobberMemory();
    }
}
BENCHMARK(BM_ShuffleDefault)->Arg(256)->Arg(65536);

